cat > /tmp/debug_refund.js << 'EOF'
import assert from 'node:assert/strict';
import { addProduct, createTestApp, ON_ADDRESS, signUp } from './src/lib/testing.ts';
import { markPaid } from './src/billing/service.ts';

function threeLineOrder() {
  const app = createTestApp();
  const customer = signUp(app.ctx, 'buyer@example.com', { address: ON_ADDRESS });
  const admin = signUp(app.ctx, 'admin@example.com', { admin: true });
  const products = [333, 333, 333].map((price) => addProduct(app.ctx, { price }));
  for (const p of products) {
    app.call('POST', '/cart/items', { token: customer.token, body: { productId: p.id, quantity: 1 } });
  }
  const order = app.call('POST', '/checkout', { token: customer.token, body: { addressIndex: 0 } }).body;
  return { app, customer, admin, products, order };
}

const t = threeLineOrder();
markPaid(t.app.ctx, t.order.invoiceId);
const invoice = t.app.ctx.store.invoices.require(t.order.invoiceId);

console.log('Invoice lines:');
for (let i = 0; i < invoice.lines.length; i++) {
  const line = invoice.lines[i];
  console.log(`Line ${i}:`, {
    productId: line.productId,
    net: line.net,
    discount: line.discount,
    tax: line.tax,
    refund: line.net - line.discount + line.tax,
  });
}
console.log('Total should refund to:', invoice.total);

const refund = (productId, token = t.admin.token) =>
  t.app.call('POST', `/invoices/${t.order.invoiceId}/refunds`, { token, body: { productId } });

const amounts = t.products.map((p) => (refund(p.id).body).amount);
console.log('Refund amounts:', amounts);
console.log('Sum:', amounts.reduce((a, b) => a + b, 0));
EOF
node /tmp/debug_refund.js

